package com.chain.contracts

import kotlinx.coroutines.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

data class Transaction(val sender: String, val recipient: String, val amount: Long, val memo: String)
data class Block(val index: Int, val transactions: List<Transaction>, val previousHash: String, val nonce: Long)

class SmartContractEngine {
    private val ledger = ConcurrentHashMap<String, Long>()
    private val templateCache = ConcurrentHashMap<String, String>()
    private val auditLog = mutableListOf<String>()
    private val contractMetadata = ConcurrentHashMap<String, String>()

    companion object {
        private const val MAX_MEMO_LENGTH = 256
        private val SAFE_MEMO_PATTERN = Regex("""^[\w\s.,!?@#%&*()\-+=:;'"\[\]{}|/\\]+$""")
    }

    fun initializeAccounts(accounts: Map<String, Long>) {
        accounts.forEach { (k, v) -> ledger[k] = v }
    }

    private fun computeHash(data: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    suspend fun executeContract(tx: Transaction): Result<String> = coroutineScope {
        val validationDeferred = async { validateTransaction(tx) }
        val templateDeferred = async { resolveContractTemplate(tx) }

        val isValid = validationDeferred.await()
        if (!isValid) return@coroutineScope Result.failure(Exception("Invalid transaction"))

        val renderedOutput = templateDeferred.await()

        // Perform the transfer atomically; abort if funds became insufficient
        // between validation and execution (prevents TOCTOU / double-spend).
        val transferResult = async { performTransfer(tx) }
        if (!transferResult.await()) {
            return@coroutineScope Result.failure(Exception("Transfer failed: insufficient funds"))
        }

        logAuditEntry(tx, renderedOutput)
        Result.success(renderedOutput)
    }

    private suspend fun validateTransaction(tx: Transaction): Boolean = withContext(Dispatchers.Default) {
        delay(10) // simulate consensus delay
        val senderBalance = ledger.getOrDefault(tx.sender, 0L)
        tx.amount > 0 && senderBalance >= tx.amount && tx.sender != tx.recipient &&
            tx.memo.length <= MAX_MEMO_LENGTH
    }

    private suspend fun resolveContractTemplate(tx: Transaction): String = withContext(Dispatchers.IO) {
        val templateKey = deriveTemplateKey(tx)
        templateCache.getOrPut(templateKey) {
            loadAndRenderTemplate(tx)
        }
    }

    private fun deriveTemplateKey(tx: Transaction): String {
        return computeHash("${tx.sender}:${tx.recipient}:${tx.amount}")
    }

    private fun loadAndRenderTemplate(tx: Transaction): String {
        val baseTemplate = getBaseTemplate()
        return renderWithDirectives(baseTemplate, tx)
    }

    private fun getBaseTemplate(): String {
        return """Transfer Receipt
            |From: {{sender}}
            |To: {{recipient}}
            |Amount: {{amount}}
            |Memo: {{memo}}
            |Generated: {{timestamp}}""".trimMargin()
    }

    private fun renderWithDirectives(template: String, tx: Transaction): String {
        var result = template
        result = result.replace("{{sender}}", sanitizeOutput(tx.sender))
        result = result.replace("{{recipient}}", sanitizeOutput(tx.recipient))
        result = result.replace("{{amount}}", tx.amount.toString())
        result = result.replace("{{memo}}", sanitizeMemo(tx.memo))
        result = result.replace("{{timestamp}}", System.currentTimeMillis().toString())
        return result
    }

    private fun sanitizeOutput(input: String): String {
        // Strip any HTML/SSI-like directives entirely
        return input.replace(Regex("""<[^>]*>"""), "").replace(Regex("""<!--.*?-->"""), "")
    }

    private fun sanitizeMemo(input: String): String {
        // Remove all HTML comments and tags which could contain SSI directives
        var sanitized = input.replace(Regex("""<!--.*?-->"""), "[removed]")
        sanitized = sanitized.replace(Regex("""<[^>]*>"""), "[removed]")
        // Truncate to max length
        if (sanitized.length > MAX_MEMO_LENGTH) {
            sanitized = sanitized.substring(0, MAX_MEMO_LENGTH)
        }
        return sanitized
    }

    private suspend fun performTransfer(tx: Transaction): Boolean = withContext(Dispatchers.Default) {
        // Atomically debit the sender only if sufficient funds remain at execution time.
        var debited = false
        ledger.compute(tx.sender) { _, balance ->
            val current = balance ?: 0L
            if (current >= tx.amount) {
                debited = true
                current - tx.amount
            } else {
                current
            }
        }
        if (!debited) return@withContext false
        ledger.compute(tx.recipient) { _, balance -> (balance ?: 0L) + tx.amount }
        true
    }

    private fun logAuditEntry(tx: Transaction, output: String) {
        val entry = "[${System.currentTimeMillis()}] ${tx.sender} -> ${tx.recipient}: ${tx.amount} | Output: ${sanitizeOutput(output)}"
        synchronized(auditLog) {
            auditLog.add(entry)
        }
    }

    fun getBalance(account: String): Long = ledger.getOrDefault(account, 0L)
    fun getAuditLog(): List<String> = synchronized(auditLog) { auditLog.toList() }
}

fun main() = runBlocking {
    val engine = SmartContractEngine()
    engine.initializeAccounts(mapOf("alice" to 1000L, "bob" to 500L))

    val tx = Transaction("alice", "bob", 100L, "Payment for services")
    val result = engine.executeContract(tx)
    println(result.getOrNull())
}
